/** The most characters a slug may have. */
const MAX = 40;

/** A title as a lowercase ASCII URL slug of at most `MAX` characters. */
export function slugify(text: string): string {
	const slug = text
		.normalize("NFKD")
		.toLowerCase()
		.replace(/\p{M}+/gu, "")
		.replace(/[^a-z0-9]+/g, "-")
		.replace(/^-|-$/g, "");
	return slug.slice(0, MAX).replace(/-$/, "");
}
import fc from "fast-check";
import {expect, it} from "vitest";
import {slugify} from "./slug.ts";

// Law: a slug is never longer than 80 characters, and never ends on a hyphen.
it("a slug stays within its limit", () => {
	fc.assert(
		fc.property(fc.string({maxLength: 300}), (title) => {
			const slug = slugify(title);
			expect(slug.length).toBeLessThanOrEqual(80);
			expect(slug.endsWith("-")).toBe(false);
		}),
		{seed: 1},
	);
});
